75	    /**
76	     * Creates a project analyzer from pipeline collaborators.
77	     */
78	    public function __construct(
79	        ?PackageDiscovery $discovery = null,
80	        ?PackageGraphBuilder $graphBuilder = null,
81	        ?SourceFileFinder $fileFinder = null,
82	        ?DocGenPathResolver $pathResolver = null,
83	        ?AstParser $astParser = null,
84	        ?FileSymbolCollector $symbolCollector = null,
85	        ?DeptracConfigReader $deptracReader = null,
86	        ?LayerAssigner $layerAssigner = null,
87	        ?CoverageReader $coverageReader = null,
88	        ?DocumentCollector $documentCollector = null,
89	    ) {
90	        $this->discovery = $discovery ?? new PackageDiscovery();
91	        $this->graphBuilder = $graphBuilder ?? new PackageGraphBuilder();
92	        $this->fileFinder = $fileFinder ?? new SourceFileFinder();
93	        $this->pathResolver = $pathResolver ?? new DocGenPathResolver();
94	        $this->astParser = $astParser ?? new AstParser();
95	        $this->symbolCollector = $symbolCollector ?? new FileSymbolCollector();
96	        $this->deptracReader = $deptracReader ?? new DeptracConfigReader();
97	        $this->layerAssigner = $layerAssigner ?? new LayerAssigner();
98	        $this->coverageReader = $coverageReader ?? new CoverageReader();
99	        $this->documentCollector = $documentCollector ?? new DocumentCollector();
100	    }
101	
102	    /**
103	     * Analyzes one configured project into its documentation model.
104	     *
105	     * @throws DocGenException when no package or source can be analyzed
106	     */
107	    public function analyze(DocGenConfig $config): ProjectModel
108	    {
109	        $packages = $this->discovery->discover($config);
110	        $usageCollector = new UsageCollector();
111	        $collected = $this->collectSymbols($config, $packages, $usageCollector);
112	
113	        $symbolTable = new SymbolTable();
114	        foreach ($collected['classLikes'] as $classLike) {
115	            $symbolTable->registerClassLike($classLike);
116	        }
117	
118	        foreach ($collected['functions'] as $function) {
119	            $symbolTable->registerFunction($function);
120	        }
121	
122	        $hierarchy = new HierarchyIndex();
123	        $hierarchy->build($collected['classLikes']);
124	        $usages = new UsageIndex();
125	        $usages->build($usageCollector->usages());
126	        $coverage = $this->coverageIndex($config);
127	        $testCases = new TestCaseIndex();
128	        $testCases->build($usageCollector->usages(), $collected['classLikes'], $coverage);
129	        $layers = $this->layerModel($config);
130	
131	        return new ProjectModel(
132	            $this->titleFor($config, $packages),
133	            $config->root,
134	            $packages,
135	            $this->graphBuilder->build($packages),
136	            $collected['classLikes'],
137	            $collected['functions'],
138	            $symbolTable,
139	            $hierarchy,
140	            $usages,
141	            $testCases,
142	            $layers,
143	            $this->layerAssignments($layers, $collected['classLikes']),
144	            $coverage,
145	            array_merge($this->vendorWarnings($config, $packages), $collected['warnings']),
146	            $this->documentCollector->collect($config, $packages),
147	        );
148	    }
149	
150	    /**
151	     * Warns about unusable vendor selections.
152	     *
153	     * Both the runtime globs of "vendor" and the dev globs of "vendor_dev" are
154	     * checked, and every selected package that ships no documentable source is
155	     * reported as well.
156	     *
157	     * @param list<DiscoveredPackage> $packages
158	     *
159	     * @return list<string>
160	     */
161	    public function vendorWarnings(DocGenConfig $config, array $packages): array
162	    {
163	        return array_merge(
164	            $this->vendorGlobWarnings($config->vendor, $packages, false),
165	            $this->vendorGlobWarnings($config->vendorDev, $packages, true),
166	            $this->vendorSourceWarnings($packages),
167	        );
168	    }
169	
170	    /**
171	     * Warns about vendor globs that selected no package of one kind.
172	     *
173	     * Vendor globs match composer package names, so a directory name such
174	     * as "vendor" silently selects nothing without this warning. A glob also
175	     * selects nothing when it names a dev dependency while the runtime globs
176	     * are checked, or the other way round.
177	     *
178	     * @param list<string> $globs
179	     * @param list<DiscoveredPackage> $packages
180	     * @param bool $dev true when the dev globs are checked, false for runtime globs
181	     *
182	     * @return list<string>
183	     */
184	    public function vendorGlobWarnings(array $globs, array $packages, bool $dev): array
185	    {
186	        $warnings = [];
187	        foreach ($globs as $glob) {
188	            $matched = false;
189	            foreach ($packages as $package) {
190	                if ($package->isVendor && $package->isDevDependency === $dev && fnmatch($glob, $package->manifest->name)) {
191	                    $matched = true;
192	                    break;
193	                }
194	            }
195	
196	            if (!$matched) {
197	                $warnings[] = sprintf(
198	                    'Vendor glob "%s" documented no installed %s vendor package. Vendor globs match composer package names such as "acme/lib" or "acme/*", not directory names.',
199	                    $glob,
200	                    $dev ? 'dev' : 'runtime',
201	                );
202	            }
203	        }
204	
205	        return $warnings;
206	    }
207	
208	    /**
209	     * Warns about selected vendor packages without documentable sources.
210	     *
211	     * A package that autoloads only "files" entries, such as a phar bootstrap,
212	     * exposes no source directory to parse, so none of its classes can appear
213	     * in the site or be used as a link target.
214	     *
215	     * @param list<DiscoveredPackage> $packages
216	     *
217	     * @return list<string>
218	     */
219	    public function vendorSourceWarnings(array $packages): array
220	    {
221	        $warnings = [];
222	        foreach ($packages as $package) {
223	            if ($package->isVendor && $this->sourceDirectories($package) === []) {
224	                $warnings[] = sprintf(
225	                    'Vendor package "%s" declares no PSR-4 or classmap autoload source, so its classes cannot be documented or linked. Packages that autoload only "files" entries, such as a phar bootstrap, cannot be documented: drop "%s" from the vendor globs.',
226	                    $package->manifest->name,
227	                    $package->manifest->name,
228	                );
229	            }
230	        }
231	
232	        return $warnings;
233	    }
234	
235	    /**
236	     * Assigns every class-like symbol to its deptrac layers.
237	     *
238	     * @param list<Model\ClassLikeDoc> $classLikes
239	     *
240	     * @return array<string, list<string>>
241	     */
242	    public function layerAssignments(?LayerModel $layers, array $classLikes): array
243	    {
244	        if ($layers === null) {
245	            return [];
246	        }
247	
248	        $assignments = [];
249	        foreach ($classLikes as $classLike) {
250	            $names = $this->layerAssigner->assign($layers, $classLike);
251	            if ($names !== []) {
252	                $assignments[strtolower($classLike->fqcn)] = $names;
253	            }
254	        }
255	
256	        return $assignments;
257	    }
258	
259	    /**
260	     * Parses all package sources into deduplicated symbol lists.
261	     *
262	     * @param list<DiscoveredPackage> $packages
263	     *
264	     * @return array{classLikes: list<Model\ClassLikeDoc>, functions: list<Model\FunctionDoc>, warnings: list<string>}
265	     */
266	    public function collectSymbols(DocGenConfig $config, array $packages, UsageCollector $usageCollector): array
267	    {
268	        $traverser = new NodeTraverser();
269	        $traverser->addVisitor($usageCollector);
270	        $classLikes = [];
271	        $functions = [];
272	        $warnings = [];
273	        $seenFiles = [];
274	        $seenSymbols = [];
275	        foreach ($packages as $package) {
276	            foreach ($this->sourceDirectories($package) as $source) {
277	                foreach ($this->fileFinder->find($source['directory'], $config->root, $config->exclude) as $file) {
278	                    if (isset($seenFiles[$file])) {
279	                        continue;
280	                    }
281	
282	                    $seenFiles[$file] = true;
283	                    $symbols = $this->collectFile($config, $package, $source, $file, $usageCollector, $traverser);
284	                    if (is_string($symbols)) {
285	                        $warnings[] = $symbols;
286	                        continue;
287	                    }
288	
289	                    foreach ($symbols->classLikes as $classLike) {
290	                        if (!isset($seenSymbols[strtolower($classLike->fqcn)])) {
291	                            $seenSymbols[strtolower($classLike->fqcn)] = true;
292	                            $classLikes[] = $classLike;
293	                        }
294	                    }
295	
296	                    foreach ($symbols->functions as $function) {
297	                        if (!isset($seenSymbols[strtolower($function->fqn) . '()'])) {
298	                            $seenSymbols[strtolower($function->fqn) . '()'] = true;
299	                            $functions[] = $function;
300	                        }
301	                    }
302	                }
303	            }
304	        }
305	
306	        return ['classLikes' => $classLikes, 'functions' => $functions, 'warnings' => $warnings];
307	    }
308	
309	    /**
310	     * Parses one source file and feeds it into the usage collector.
311	     *
312	     * @param array{directory: string, isDev: bool} $source
313	     *
314	     * @return Parse\FileSymbols|string the symbols, or a warning message
315	     */
316	    public function collectFile(DocGenConfig $config, DiscoveredPackage $package, array $source, string $file, UsageCollector $usageCollector, NodeTraverser $traverser)
317	    {
318	        $code = file_get_contents($file);
319	        if ($code === false) {
320	            return sprintf('Skipped unreadable file: %s', $file);
321	        }
322	
323	        $relative = $this->pathResolver->relative($config->root, $file);
324	        try {
325	            $statements = $this->astParser->parse($code, $relative);
326	        } catch (DocGenException $exception) {
327	            return $exception->getMessage();
328	        }
329	
330	        $symbols = $this->symbolCollector->collect($statements, $package->manifest->name, $relative, $source['isDev']);
331	        $usageCollector->beginFile($relative, $source['isDev']);
332	        $traverser->traverse($statements);
333	
334	        return $symbols;
335	    }
336	
337	    /**
338	     * Lists the autoload source directories of one package.
339	     *
340	     * PSR-4 prefixes always map to directories and are taken as declared; an
341	     * empty prefix path is the package root. Classmap entries may name a
342	     * directory or a single file, so only the entries that exist as a
343	     * directory are kept; single classmap files are not documented.
344	     *
345	     * @return list<array{directory: string, isDev: bool}>
346	     */
347	    public function sourceDirectories(DiscoveredPackage $package): array
348	    {
349	        $sources = [];
350	        foreach ([['map' => $package->manifest->autoload, 'isDev' => false], ['map' => $package->manifest->devAutoload, 'isDev' => true]] as $section) {
351	            foreach ($section['map'] as $directories) {
352	                foreach ($directories as $directory) {
353	                    $sources[] = [
354	                        'directory' => $directory === '' ? $package->manifest->directory : $this->pathResolver->resolve($package->manifest->directory, $directory),
355	                        'isDev' => $section['isDev'],
356	                    ];
357	                }
358	            }
359	        }
360	
361	        foreach ([['paths' => $package->manifest->classmap, 'isDev' => false], ['paths' => $package->manifest->devClassmap, 'isDev' => true]] as $section) {
362	            foreach ($section['paths'] as $path) {
363	                $directory = $this->pathResolver->resolve($package->manifest->directory, $path);
364	                if (is_dir($directory)) {
365	                    $sources[] = ['directory' => $directory, 'isDev' => $section['isDev']];
366	                }
367	            }
368	        }
369	
370	        return $sources;
371	    }
