373	    /**
374	     * Loads the deptrac layer model when a configuration is available.
375	     *
376	     * @throws DocGenException when a configured deptrac file is missing
377	     */
378	    public function layerModel(DocGenConfig $config): ?LayerModel
379	    {
380	        if ($config->deptrac !== null) {
381	            return $this->deptracReader->read($this->pathResolver->resolve($config->root, $config->deptrac));
382	        }
383	
384	        $default = $config->root . '/deptrac.yaml';
385	        if (is_file($default)) {
386	            return $this->deptracReader->read($default);
387	        }
388	
389	        return null;
390	    }
391	
392	    /**
393	     * Loads the coverage index when a report directory is configured.
394	     *
395	     * @throws DocGenException when the configured report directory is missing
396	     */
397	    public function coverageIndex(DocGenConfig $config): ?CoverageIndex
398	    {
399	        if ($config->coverage === null) {
400	            return null;
401	        }
402	
403	        return $this->coverageReader->read($this->pathResolver->resolve($config->root, $config->coverage), $config->root);
404	    }
405	
406	    /**
407	     * Determines the site title from the configuration and packages.
408	     *
409	     * @param list<DiscoveredPackage> $packages
410	     */
411	    public function titleFor(DocGenConfig $config, array $packages): string
412	    {
413	        if ($config->title !== null) {
414	            return $config->title;
415	        }
416	
417	        foreach ($packages as $package) {
418	            if (!$package->isVendor && realpath($package->manifest->directory) === realpath($config->root)) {
419	                return $package->manifest->name;
420	            }
421	        }
422	
423	        return basename($config->root);
424	    }
