56	    /**
57	     * Creates a class-like page renderer from its section collaborators.
58	     */
59	    public function __construct(
60	        ?PageChrome $chrome = null,
61	        ?SidebarHtml $sidebar = null,
62	        ?BreadcrumbHtml $breadcrumb = null,
63	        ?SignatureHtml $signature = null,
