83	    /**
84	     * Renders one complete class-like page document.
85	     */
86	    public function render(RenderKit $services, ClassLikeDoc $classLike): string
87	    {
88	        $pagePath = $services->url->classLikePage($classLike);
89	        $context = $this->context($services, $pagePath, $classLike, []);
90	        $crumbs = [['label' => $classLike->packageName, 'path' => $services->url->packagePage($classLike->packageName)]];
91	        if ($classLike->namespace !== '') {
92	            $crumbs[] = ['label' => $classLike->namespace, 'path' => $services->url->namespacePage($classLike->packageName, $classLike->namespace)];
93	        }
94	
95	        $crumbs[] = ['label' => $classLike->shortName, 'path' => null];
96	
97	        return $this->chrome->page(
98	            $services,
99	            $pagePath,
100	            $classLike->shortName,
101	            $this->breadcrumb->build($services, $pagePath, $crumbs),
102	            $this->sidebar->build($services, $pagePath, new SidebarScope(
103	                $classLike->packageName,
104	                $classLike->namespace,
105	                $classLike->fqcn,
106	                $this->sections($services, $classLike),
107	            )),
108	            $this->content($services, $pagePath, $classLike, $context),
109	        );
110	    }
