112	    /**
113	     * Lists the sections this page will render, in page order.
114	     *
115	     * Every anchor carries the state of the section it points at, so the
116	     * navigation of a page narrows exactly as the page itself does.
117	     *
118	     * @return list<array{id: string, label: string, status: string}>
119	     */
120	    public function sections(RenderKit $services, ClassLikeDoc $classLike): array
121	    {
122	        $constants = $this->visibleMembers($classLike->constants);
123	        $properties = $this->visibleMembers($classLike->properties);
124	        $methods = $this->visibleMembers($classLike->methods);
125	        $candidates = [
126	            ['id' => 'aliases', 'label' => 'Type aliases', 'present' => ($classLike->docBlock !== null ? $classLike->docBlock->aliases : []) !== [], 'status' => $services->diff->headerStatus($classLike->fqcn)],
127	            ['id' => 'cases', 'label' => 'Cases', 'present' => $classLike->enumCases !== [], 'status' => $this->sectionStatus($services, $classLike, DiffKey::ENUM_CASE, $classLike->enumCases)],
128	            ['id' => 'constants', 'label' => 'Constants', 'present' => $constants !== [], 'status' => $this->sectionStatus($services, $classLike, DiffKey::CONSTANT, $constants)],
129	            ['id' => 'properties', 'label' => 'Properties', 'present' => $properties !== [], 'status' => $this->sectionStatus($services, $classLike, DiffKey::PROPERTY, $properties)],
130	            ['id' => 'methods', 'label' => 'Methods', 'present' => $methods !== [], 'status' => $this->sectionStatus($services, $classLike, DiffKey::METHOD, $methods)],
131	            ['id' => 'private-surface', 'label' => 'Private surface', 'present' => $this->privateSurface->members($classLike) !== [], 'status' => $services->diff->combine($this->privateSurface->statuses($services, $classLike))],
132	            ['id' => 'test-cases', 'label' => 'Test cases', 'present' => $services->model->testCases->forType($classLike->fqcn) !== [], 'status' => DiffStatus::SAME],
133	            ['id' => 'relations', 'label' => 'Relations', 'present' => true, 'status' => DiffStatus::SAME],
134	        ];
135	
136	        $sections = [];
137	        foreach ($candidates as $candidate) {
138	            if ($candidate['present']) {
139	                $sections[] = ['id' => $candidate['id'], 'label' => $candidate['label'], 'status' => $candidate['status']];
140	            }
141	        }
142	
143	        return $sections;
144	    }
145	
146	    /**
147	     * Filters the members that are part of the documented public surface.
148	     *
149	     * @template T of \PhpAiToolkit\DocGen\Analysis\Model\ConstantDoc|\PhpAiToolkit\DocGen\Analysis\Model\PropertyDoc|\PhpAiToolkit\DocGen\Analysis\Model\MethodDoc
150	     *
151	     * @param list<T> $members
152	     *
153	     * @return list<T>
154	     */
155	    public function visibleMembers(array $members): array
156	    {
157	        $visible = [];
158	        foreach ($members as $member) {
159	            if ($member->visibility !== 'private') {
160	                $visible[] = $member;
161	            }
162	        }
163	
164	        return $visible;
165	    }
