167	    /**
168	     * Builds the type resolution context of this page.
169	     *
170	     * @param list<\PhpAiToolkit\DocGen\Analysis\Model\TemplateDoc> $extraTemplates
171	     */
172	    public function context(RenderKit $services, string $pagePath, ClassLikeDoc $classLike, array $extraTemplates): TypeRenderContext
173	    {
174	        $templates = [];
175	        foreach (array_merge($classLike->docBlock !== null ? $classLike->docBlock->templates : [], $extraTemplates) as $template) {
176	            $templates[] = $template->name;
177	        }
178	
179	        $aliases = [];
180	        foreach ($classLike->docBlock !== null ? $classLike->docBlock->aliases : [] as $alias) {
181	            $aliases[$alias->name] = '#alias.' . $alias->name;
182	        }
183	
184	        return new TypeRenderContext($pagePath, $classLike->namespace, $classLike->useMap, $templates, $aliases, $services->model->symbolTable);
185	    }
