187	    /**
188	     * Renders the page content of one class-like symbol.
189	     */
190	    public function content(RenderKit $services, string $pagePath, ClassLikeDoc $classLike, TypeRenderContext $context): string
191	    {
192	        $escaper = $services->escaper;
193	        $html = '<div class="symbol-head">';
194	        $html .= sprintf('<h1><span class="chip chip-kind k-%s">%s</span>%s</h1>', $classLike->kind, $classLike->kind, $escaper->e($classLike->shortName));
195	        $html .= '<div class="symbol-meta">';
196	        foreach ($services->model->layerAssignments[strtolower($classLike->fqcn)] ?? [] as $layer) {
197	            $html .= sprintf(
198	                '<a class="chip chip-layer" href="%s" title="deptrac layer">%s</a>',
199	                $escaper->e($services->url->href($pagePath, $services->url->layerPage($classLike->packageName, $layer))),
200	                $escaper->e($layer),
201	            );
202	        }
203	
204	        $html .= sprintf(
205	            '<a class="src-link" href="%s">%s:%d</a>',
206	            $escaper->e($services->url->href($pagePath, $services->url->sourcePage($classLike->file)) . '#L' . $classLike->startLine),
207	            $escaper->e($classLike->file),
208	            $classLike->startLine,
209	        );
210	        $html .= '</div></div>' . "\n";
211	        $html .= $this->banner->render($services, $services->diff->classLikeStatus($classLike->fqcn));
212	        $html .= $this->signature->classSignature($services, $classLike, $context);
213	        $html .= $this->docText->render($services, $classLike->docBlock, $context);
214	        $html .= $this->aliasSection($services, $pagePath, $classLike, $context);
215	        $html .= $this->member->tagExamples($services, $classLike->docBlock);
216	        $html .= $this->memberSections($services, $pagePath, $classLike, $context);
217	        $html .= $this->privateSurface->section($services, $classLike, $context);
218	        $html .= $this->testCaseSection($services, $pagePath, $classLike);
219	
220	        return $html . $this->relations->build($services, $pagePath, $classLike);
221	    }
