226	    public function testCaseSection(RenderKit $services, string $pagePath, ClassLikeDoc $classLike): string
227	    {
228	        $testCases = $services->model->testCases->forType($classLike->fqcn);
229	        if ($testCases === []) {
230	            return '';
231	        }
232	
233	        $dedicated = [];
234	        $others = [];
235	        foreach ($testCases as $testCase) {
236	            if ($this->isDedicatedTest($testCase->testClass, $classLike->shortName)) {
237	                $dedicated[] = $testCase;
238	            } else {
239	                $others[] = $testCase;
