import sys
from collections import defaultdict

path = sys.argv[1]
self_cost = defaultdict(int)
incl_cost = defaultdict(int)
call_count = defaultdict(int)
names = {}

cur_fn = None
pending_call = False

with open(path, 'r', errors='replace') as f:
    for line in f:
        line = line.rstrip('\n')
        if not line:
            continue
        c = line[0]
        if c == 'f':
            if line.startswith('fn='):
                v = line[3:]
                # (id) name  or  (id)
                if v.startswith('('):
                    idx = v.find(')')
                    fid = v[1:idx]
                    rest = v[idx+1:].strip()
                    if rest:
                        names[fid] = rest
                    cur_fn = names.get(fid, fid)
                else:
                    cur_fn = v
                pending_call = False
            continue
        if c == 'c':
            if line.startswith('calls='):
                pending_call = True
            continue
        if c.isdigit() or c == '*' or c == '-' or c == '+':
            parts = line.split()
            if len(parts) < 2:
                continue
            try:
                cost = int(parts[1])
            except ValueError:
                continue
            if pending_call:
                incl_cost[cur_fn] += cost
                call_count[cur_fn] += 1
                pending_call = False
            else:
                self_cost[cur_fn] += cost

total = sum(self_cost.values())
print("total self cost:", total)
print()
print("%-70s %12s %7s" % ("function", "self", "pct"))
for fn, cost in sorted(self_cost.items(), key=lambda kv: -kv[1])[:45]:
    print("%-70s %12d %6.2f%%" % (fn[:70], cost, 100.0*cost/total))
print()
print("--- inclusive (cost attributed at call sites) ---")
print("%-70s %14s %10s" % ("function", "incl", "calls"))
for fn, cost in sorted(incl_cost.items(), key=lambda kv: -kv[1])[:45]:
    print("%-70s %14d %10d" % (fn[:70], cost, call_count[fn]))

