/**
 * Deals items into one job per worker, balanced by weight.
 *
 * @template TItem
 *
 * @param list<TItem> $items
 * @param callable(TItem): int $weight the relative cost of one item
 * @param int $jobs how many jobs to deal into, at least one
 *
 * @return list<list<TItem>> one list per job, each in original order
 */
public function schedule(array $items, callable $weight, int $jobs): array
{
    $count = min(max($jobs, 1), count($items));
    if ($count < 2) {
        return $items === [] ? [] : [$items];
    }

    $positions = [];
    $weights = [];
    foreach ($items as $position => $item) {
        $positions[$position] = $position;
        $weights[$position] = $weight($item);
    }

    usort($positions, static fn (int $a, int $b): int => [$weights[$b], $a] <=> [$weights[$a], $b]);
    $dealt = [];
    foreach ($positions as $order => $position) {
        $dealt[$order % $count][] = $position;
    }

    $scheduled = [];
    foreach ($dealt as $job) {
        usort($job, static fn (int $a, int $b): int => $a <=> $b);
        $scheduled[] = $this->itemsAt($items, $job);
    }

    return $scheduled;
}

/**
 * Picks the items at the given positions, keeping that order.
 *
 * @template TItem
 *
 * @param list<TItem> $items
 * @param list<int> $positions
 *
 * @return list<TItem>
 */
public function itemsAt(array $items, array $positions): array
{
    $picked = [];
    foreach ($positions as $position) {
        $picked[] = $items[$position];
    }

    return $picked;
}

