public function collectSymbols(DocGenConfig $config, array $packages, ?int $workers = null): array
{
    $parsed = [];
    foreach ($this->workers->map(
        $this->jobsOf($this->sourceFiles($config, $packages), $workers),
        fn (array $job): array => $this->parseJob($config, $job),
    ) as $result) {
        foreach (is_array($result) ? $result : [] as $file) {
            $parsed[] = $file;
        }
    }

    usort($parsed, static fn (array $a, array $b): int => $a['index'] <=> $b['index']);

    return $this->merged($parsed);
}

/**
 * Lists every source file to parse, in discovery order and once each.
 *
 * @param list<DiscoveredPackage> $packages
 *
 * @return list<array{index: int, package: DiscoveredPackage, source: array{directory: string, isDev: bool}, file: string}>
 */
public function sourceFiles(DocGenConfig $config, array $packages): array
{
    $found = [];
    $seenFiles = [];
    foreach ($packages as $package) {
        foreach ($this->sourceDirectories($package) as $source) {
            foreach ($this->fileFinder->find($source['directory'], $config->root, $config->exclude) as $file) {
                if (isset($seenFiles[$file])) {
                    continue;
                }

                $seenFiles[$file] = true;
                $found[] = ['index' => count($found), 'package' => $package, 'source' => $source, 'file' => $file];
            }
        }
    }

    return $found;
}

/**
 * Splits the source files into one balanced job per worker.
 *
 * @param list<array{index: int, package: DiscoveredPackage, source: array{directory: string, isDev: bool}, file: string}> $files
 * @param ?int $workers how many workers to use, or null for the default
 *
 * @return list<list<array{index: int, package: DiscoveredPackage, source: array{directory: string, isDev: bool}, file: string}>>
 */
public function jobsOf(array $files, ?int $workers): array
{
    return $this->scheduler->schedule(
        $files,
        static fn (array $file): int => (int) @filesize($file['file']),
        $this->scheduler->workerCount($this->workerCount->resolve($workers), count($files)),
    );
}

/**
 * Parses the files of one job into per-file results.
 *
 * One collector serves the whole job, as it served the whole project
 * before there were jobs, and the usages it gathered are cut back apart
 * per file afterwards. The merge needs them per file because jobs hold
 * interleaved files, while the collector is far too expensive to build
 * once per file.
 *
 * @param list<array{index: int, package: DiscoveredPackage, source: array{directory: string, isDev: bool}, file: string}> $job
 *
 * @return list<array{index: int, warning: ?string, symbols: ?Parse\FileSymbols, usages: list<Reference\Usage>}>
 */
public function parseJob(DocGenConfig $config, array $job): array
{
    $collector = new UsageCollector();
    $traverser = new NodeTraverser();
    $traverser->addVisitor($collector);
    $parsed = [];
    $offsets = [];
    foreach ($job as $file) {
        $offsets[] = count($collector->usages());
        $symbols = $this->collectFile($config, $file['package'], $file['source'], $file['file'], $collector, $traverser);
        $parsed[] = [
            'index' => $file['index'],
            'warning' => is_string($symbols) ? $symbols : null,
            'symbols' => is_string($symbols) ? null : $symbols,
            'usages' => [],
        ];
    }

    return $this->sliced($parsed, $offsets, $collector->usages());
}

/**
 * Gives every file of a job the usages that were found in it.
 *
 * @param list<array{index: int, warning: ?string, symbols: ?Parse\FileSymbols, usages: list<Reference\Usage>}> $parsed
 * @param list<int> $offsets where the usages of each file start
 * @param list<Reference\Usage> $usages every usage the job collected
 *
 * @return list<array{index: int, warning: ?string, symbols: ?Parse\FileSymbols, usages: list<Reference\Usage>}>
 */
public function sliced(array $parsed, array $offsets, array $usages): array
{
    $total = count($usages);
    foreach ($parsed as $position => $file) {
        $start = $offsets[$position] ?? $total;
        $parsed[$position]['usages'] = array_slice($usages, $start, ($offsets[$position + 1] ?? $total) - $start);
    }

    return $parsed;
}

/**
 * Merges per-file results into the deduplicated lists of the project.
 *
 * @param list<array{index: int, warning: ?string, symbols: ?Parse\FileSymbols, usages: list<Reference\Usage>}> $parsed
 *
 * @return array{classLikes: list<Model\ClassLikeDoc>, functions: list<Model\FunctionDoc>, warnings: list<string>, usages: list<Reference\Usage>}
 */
public function merged(array $parsed): array
{
    $classLikes = [];
    $functions = [];
    $warnings = [];
    $usages = [];
    $seenSymbols = [];
    foreach ($parsed as $file) {
        foreach ($file['usages'] as $usage) {
            $usages[] = $usage;
        }

        if ($file['symbols'] === null) {
            $warnings[] = (string) $file['warning'];
            continue;
        }

        foreach ($file['symbols']->classLikes as $classLike) {
            if (!isset($seenSymbols[strtolower($classLike->fqcn)])) {
                $seenSymbols[strtolower($classLike->fqcn)] = true;
                $classLikes[] = $classLike;
            }
        }

        foreach ($file['symbols']->functions as $function) {
            if (!isset($seenSymbols[strtolower($function->fqn) . '()'])) {
                $seenSymbols[strtolower($function->fqn) . '()'] = true;
                $functions[] = $function;
            }
        }
    }

    return ['classLikes' => $classLikes, 'functions' => $functions, 'warnings' => $warnings, 'usages' => $usages];
}

